97	// buildDetailsContent builds the full scrollable content for the details view.
98	//
99	// What to do comes before why: the Fix block (status, Where, Do, Run, Effect),
100	// the Change it would make, then Why, the scanner's Output and the Refs. Each section is emitted only when
101	// it has something to say, and sections are joined by exactly one blank line.
102	func (m Model) buildDetailsContent() string {
103		if m.selectedFinding == nil {
104			return theme.Bg("No finding selected")
105		}
106	
107		f := *m.selectedFinding
108		t := newDetailsText(m.detailsTextWidth())
109	
110		var sections []string
111		for _, section := range [][]string{
112			m.detailsHeader(f, t),
113			m.detailsFix(f, t),
114			m.detailsChange(f, t),
115			m.detailsWhy(f, t),
116			m.detailsOutput(f, t),
117			m.detailsReferences(f, t),
118		} {
119			if len(section) > 0 {
120				sections = append(sections, strings.Join(section, "\n"))
121			}
122		}
123	
124		return lipgloss.NewStyle().
125			Padding(1).
126			Background(theme.ColorBackground).
127			Render(strings.Join(sections, "\n\n"))
128	}
