130	// detailsHeader is the severity and ID, then the title on one line: a title can
131	// carry a whole stderr line, and the Message below has the rest.
132	func (m Model) detailsHeader(f scan.Finding, t detailsText) []string {
133		sev := string(f.Severity)
134		header := m.getSeverityStyle(f.Severity).Render(sev) + theme.Bg(" ") +
135			theme.TitleStyle.Render(oneLine(f.ID, t.width-ansi.StringWidth(sev)-1))
136		title := oneLine(shortPaths(f.Title, m.scanTarget()), t.width)
137		return []string{header, t.text.Render(title)}
138	}
139	
140	// detailsFix is the Fix block: the status in words, then, with no blank line
141	// between them, where the finding is, what to do, the command to run and what the
142	// fix does. It is written in ColorText alone (DEVDESK-751, AC7): ColorDim, the
143	// sub-title and the warning colours fall under 4.5:1 on several shipped themes,
144	// so the word "Warning:" carries the warning.
145	func (m Model) detailsFix(f scan.Finding, t detailsText) []string {
146		status := m.fixStatus(f)
147		lines := t.field("Fix: ", status.Label(), t.text)
148		lines = append(lines, m.detailsWhere(f, t)...)
149		lines = append(lines, t.list("Do: ", fixSteps(f), f.Resolution, t.text)...)
150		lines = append(lines, detailsRun(f, t)...)
151		lines = append(lines, detailsRepro(f, t)...)
152		lines = append(lines, t.field("Effect: ", status.Effect, t.text)...)
153		return append(lines, t.field("Warning: ", status.Warning, t.text)...)
154	}
155	
156	// detailsWhere is the file, then the other facts that place the finding, each on
157	// its own line under the first.
158	func (m Model) detailsWhere(f scan.Finding, t detailsText) []string {
159		const label = "Where: "
160		facts := whereFacts(f, m.scanTarget())
161		if len(facts) == 0 {
162			return nil
163		}
164		first := facts[0].Value
165		if facts[0].Label != "File" {
166			first = facts[0].Label + ": " + first
167		}
168		lines := t.field(label, first, t.text)
169		for _, fc := range facts[1:] {
170			lines = append(lines, t.fieldAt(ansi.StringWidth(label), fc.Label+": ", fc.Value, t.text)...)
171		}
172		return lines
173	}
174	
175	// detailsRun is the command on one line, cut when it is wider than the column:
176	// the copy key puts the whole of it on the clipboard.
177	func detailsRun(f scan.Finding, t detailsText) []string {
178		const label = "Run: "
179		cmd, ok := runCommand(f)
180		if !ok {
181			return nil
182		}
183		return []string{t.heading(label) + t.text.Render(oneLine("$ "+cmd, t.width-ansi.StringWidth(label)))}
184	}
185	
186	// detailsWhy is the reason the finding matters: the scanner's description, the
187	// Pod Security profile, where the finding comes from and its type.
188	func (m Model) detailsWhy(f scan.Finding, t detailsText) []string {
189		var lines []string
190		if strings.TrimSpace(f.Description) != "" {
191			lines = t.block(f.Description, t.text)
192		}
193		lines = append(lines, t.field("Pod Security: ", pssLabel(f), t.text)...)
194		lines = append(lines, t.field("Source: ", f.Source, t.text)...)
195		lines = append(lines, t.field("Type: ", f.IaCType, t.text)...)
196		if len(lines) == 0 {
197			return nil
198		}
199		return append([]string{t.heading("Why:")}, lines...)
200	}
201	
202	// detailsOutput is what the scanner said about this instance, capped: the start
203	// of it is what tells two findings of one rule apart, and the rest is in the log.
204	// A message that only repeats the title or the description adds nothing.
205	func (m Model) detailsOutput(f scan.Finding, t detailsText) []string {
206		msg := strings.TrimSpace(f.Message)
207		if msg == "" || msg == strings.TrimSpace(f.Title) || msg == strings.TrimSpace(f.Description) {
208			return nil
209		}
210		lines, hidden := cappedLines(dropBlankLines(shortPaths(msg, m.scanTarget())), t.width, maxMessageLines)
211		if len(lines) == 0 {
212			return nil
213		}
214		out := []string{t.heading("Output:")}
215		for _, line := range lines {
216			out = append(out, t.text.Render(line))
217		}
218		if more := moreLines(hidden); more != "" {
219			out = append(out, theme.DimStyle.Render(more))
220		}
221		return out
222	}
223	
224	// detailsReferences are the reference URLs, one per line.
225	func (m Model) detailsReferences(f scan.Finding, t detailsText) []string {
226		if len(f.References) == 0 {
227			return nil
228		}
229		lines := []string{t.heading("Refs:")}
230		for _, ref := range f.References {
231			lines = append(lines, t.indented("  ", ref, t.text)...)
232		}
233		return lines
234	}
235	
236	// renderDetailsView renders the scrollable details viewport.
237	func (m Model) renderDetailsView() string {
238		return m.detailsViewport.View()
239	}
240	
241	// getSeverityStyle returns style for severity level (Rule 102: the palette
242	// lives in the theme, not here).
243	func (m Model) getSeverityStyle(sev scan.SeverityLevel) lipgloss.Style {
244		return theme.SeverityTextStyle(string(sev))
245	}
