247	// HeaderView interface implementation
248	
249	// packageKind says what has to move to clear a vulnerability, from the class
250	// Trivy reported. Empty for a result cached before the class was recorded: it
251	// is unknown, and is not shown rather than guessed.
252	func packageKind(class string) string {
253		switch class {
254		case scan.ClassOSPackages:
255			return "Base image package"
256		case scan.ClassLangPackages:
257			return "Application dependency"
258		}
259		return ""
260	}
