	m := cursorOnMember(t, openedGroup(t, groupedModel(t, 160), "openssl"), "CVE-2")
	m = feed(t, m, testutil.Key("enter"))
	if m.state != StateDetails || m.selectedFinding == nil || m.selectedFinding.ID != "CVE-2" {
